const lines = (n) => Array.from({ length: n }, () => ({ price: 1000, qty: 1 }));

test('total applies the 5% bulk discount once, after the customer discount, at 10 lines', () => {
  // 10,000 less 10% = 9,000; less 5% = 8,550
  assert.equal(total(lines(10), 0.1), 8550);
});

test('total applies no bulk discount below 10 lines', () => {
  // 9,000 less 10% = 8,100
  assert.equal(total(lines(9), 0.1), 8100);
});

test('total with a zero discount rate still gets only the bulk discount', () => {
  // 10,000 less 5% = 9,500
  assert.equal(total(lines(10), 0), 9500);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
